const $=s=>document.querySelector(s);let world;let saved=[];try{saved=JSON.parse(localStorage.getItem('schifferstadt-places')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));}catch{}$('#count').textContent=saved.length;
const status=t=>$('#notice').textContent=t;
function mode(m){if(!world)return;world.setMode(m);$('#orbit').classList.toggle('active',m==='orbit');$('#walk').classList.toggle('active',m==='walk');$('.motion').hidden=m!=='walk';}
$('#orbit').onclick=()=>mode('orbit');$('#walk').onclick=()=>mode('walk');$('#plus').onclick=()=>world?.zoom(-1);$('#minus').onclick=()=>world?.zoom(1);$('#home').onclick=()=>{world?.reset();mode('orbit');};$('#time').oninput=e=>{const h=Number(e.target.value);$('#hour').textContent=`${String(Math.floor(h)).padStart(2,'0')}:${h%1?'30':'00'}`;world?.setTime(h);};$('#quality').onchange=e=>world?.setQuality(e.target.checked);
for(const b of document.querySelectorAll('.motion button')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);world?.setMotion(+b.dataset.f,+b.dataset.r)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>world?.setMotion(0,0)}document.addEventListener('visibilitychange',()=>{if(document.hidden)world?.setMotion(0,0)});
$('#info').onclick=()=>$('#about').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#retry').onclick=()=>location.reload();
function persist(){try{localStorage.setItem('schifferstadt-places',JSON.stringify(saved));$('#count').textContent=saved.length;return true}catch{status('Gerätespeicher nicht verfügbar. Ort konnte nicht gespeichert werden.');return false}}
$('#save').onclick=()=>{if(!world?.getPosition().loaded){status('Bitte erst die Stadtdaten laden.');return}if(saved.length>=30){status('30 Orte gespeichert. Entferne zuerst einen Ort.');return}const p=world.getPosition();saved.push({lat:p.lat,lon:p.lon,name:`Entdeckung ${saved.length+1}`});if(persist())status('Lieblingsort auf diesem Gerät gespeichert ♡');else saved.pop()};
function renderPlaces(){const list=$('#list');list.replaceChildren();if(!saved.length){list.textContent='Noch kein Lieblingsort. Tippe in der Karte auf das Herz.';return}saved.forEach((p,i)=>{const row=document.createElement('div');row.className='bookmark';const go=document.createElement('button');go.textContent=p.name;go.onclick=()=>{if(!world){status('3D-Ansicht noch nicht verfügbar.');return}world.goTo(p.lat,p.lon);$('#bookmarks').close()};const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',`${p.name} löschen`);del.onclick=()=>{const old=saved.slice();saved.splice(i,1);if(!persist())saved=old;renderPlaces()};row.append(go,del);list.append(row)})}$('#places').onclick=()=>{renderPlaces();$('#bookmarks').showModal()};
try{const {initWorld}=await import('./engine.js');world=initWorld($('#world'),status);world.setTime(16);$('#quality').checked=!matchMedia('(pointer:coarse)').matches;}catch(e){console.error(e);status('3D-Ansicht nicht verfügbar. Die App benötigt vollständig eingebundene 3D- und Kartendaten sowie eine aktuelle Android System WebView mit WebGL. Bitte den Build prüfen.');}
